-- =====================================================================================================================
-- AptRun: Apex Institute demo roster - years of study, 91 extra students, and Alex Chen's Vault AI Interview unlock
--
-- Generated from the dev database (140 Apex students: 49 that already existed + 91 added).
-- Every statement finds its rows by EMAIL / college short_code / plan code - no ids are hard-coded - and is safe to run twice
-- (a student that already exists is skipped, an UPDATE just sets the same value again).
--
-- PREREQUISITE: 2026-11-vault-ai-interview-years-and-scores.sql has been run (it adds users.graduation_year, first_login_at,
--               vault_ai_unlocked_at, readiness_score ... that this script fills).
-- The college with short_code = 'APEX' and the plan with code = 'coder' must exist; if the college does not, nothing is inserted.
--
--   mysql -u <user> -p <database> < 2026-11-apex-students-years-and-alex-unlock.sql
-- =====================================================================================================================

-- 0. PRE-FLIGHT (read-only): both ids must be non-NULL.
SELECT (SELECT id FROM colleges WHERE short_code = 'APEX') AS apex_college_id, (SELECT id FROM plans WHERE code = 'coder') AS coder_plan_id;
SELECT COUNT(*) AS apex_students_now FROM users WHERE role = 'user' AND college_id = (SELECT id FROM colleges WHERE short_code = 'APEX');

-- ---------------------------------------------------------------------------------------------------------------------
-- 1. YEAR OF STUDY for the 49 Apex students that already exist (graduation_year: 2027 = 4th year, 2028 = 3rd year, 2029 = 2nd year)
-- ---------------------------------------------------------------------------------------------------------------------
-- 2nd year: 9 students
UPDATE users SET graduation_year = 2029 WHERE role = 'user' AND college_id = (SELECT id FROM colleges WHERE short_code = 'APEX') AND email IN ('tpo.self.two.qa@example.com', 'aarav.mehta.arena@student.apex.edu', 'arjun.patel.arena@student.apex.edu', 'tanvi.saxena.arena@student.apex.edu', 'priyanka.das.arena@student.apex.edu', 'karthik.menon.arena@student.apex.edu', 'aman.khan.arena@student.apex.edu', 'shruti.pillai.arena@student.apex.edu', 'zoya.ahmed.arena@student.apex.edu');
-- 3rd year: 11 students
UPDATE users SET graduation_year = 2028 WHERE role = 'user' AND college_id = (SELECT id FROM colleges WHERE short_code = 'APEX') AND email IN ('tpo.self.one.qa@example.com', 'pkeshri9801@gmail.com', 'arunkumarbbu00@gmail.com', 'kabir.malhotra.arena@student.apex.edu', 'sneha.reddy.arena@student.apex.edu', 'meera.joshi.arena@student.apex.edu', 'vihaan.gupta.arena@student.apex.edu', 'siddharth.jain.arena@student.apex.edu', 'pooja.hegde.arena@student.apex.edu', 'riya.kapoor.arena@student.apex.edu', 'dev.choudhary.arena@student.apex.edu');
-- 4th year: 29 students
UPDATE users SET graduation_year = 2027 WHERE role = 'user' AND college_id = (SELECT id FROM colleges WHERE short_code = 'APEX') AND email IN ('alex.chen@student.apex.edu', 'priya.desai@student.apex.edu', 'rohan.kapoor@student.apex.edu', 'tpo.self.three.qa@example.com', 'diya.nair.arena@student.apex.edu', 'ishita.verma.arena@student.apex.edu', 'rohan.kulkarni.arena@student.apex.edu', 'rahul.deshmukh.arena@student.apex.edu', 'aditi.rao.arena@student.apex.edu', 'nisha.banerjee.arena@student.apex.edu', 'yash.agarwal.arena@student.apex.edu', 'manav.singhania.arena@student.apex.edu', 'mohit.rao@student.apex.edu', 'chetna.iyer@student.apex.edu', 'aarav.nair@student.apex.edu', 'saanvi.menon@student.apex.edu', 'ishaan.mishra@student.apex.edu', 'kavya.agarwal@student.apex.edu', 'rohan.khan@student.apex.edu', 'siddharth.desai@student.apex.edu', 'shreya.singh@student.apex.edu', 'pallavi.mukherjee@student.apex.edu', 'varun.verma@student.apex.edu', 'swati.shah@student.apex.edu', 'bhavna.saxena@student.apex.edu', 'reyansh.banerjee@student.apex.edu', 'meera.iyer@student.apex.edu', 'ishaan.desai@student.apex.edu', 'rohan.patel@student.apex.edu');

-- ---------------------------------------------------------------------------------------------------------------------
-- 2. 91 NEW STUDENTS - every branch of every department x 2nd / 3rd / 4th year. Each INSERT is skipped if the e-mail exists.
--    They share one random password hash nobody knows: they are roster entries (issue a login from the TPO page if one is needed).
-- ---------------------------------------------------------------------------------------------------------------------

-- ---------------------------------------------------------------------------------------------------------------------
-- 3. The default individual (Coder) subscription every student gets when the app creates them - for the new students only.
-- ---------------------------------------------------------------------------------------------------------------------
SELECT 'App\\Models\\User', u.id, (SELECT id FROM plans WHERE code = 'coder'), 'active', u.created_at, 0, 0, u.created_at, u.created_at
FROM users u WHERE u.email LIKE '%.fill@student.apex.edu'
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.subscriber_type = 'App\\Models\\User' AND s.subscriber_id = u.id);

-- ---------------------------------------------------------------------------------------------------------------------
-- 4. ALEX CHEN: 4th year, CSE / Engineering, past his 45 days, Vault AI Interview unlocked.
--    The earliest first sign-in wins and an unlock already on record is kept, so re-running (or an older record) never moves them.
-- ---------------------------------------------------------------------------------------------------------------------
UPDATE users SET graduation_year = 2027,
  first_login_at = COALESCE(LEAST(first_login_at, '2026-09-08 07:19:43'), '2026-09-08 07:19:43'),
  vault_ai_unlocked_at = COALESCE(vault_ai_unlocked_at, '2026-10-28 07:19:43')
WHERE email = 'alex.chen@student.apex.edu' AND role = 'user';

-- ---------------------------------------------------------------------------------------------------------------------
-- 5. VERIFY (read-only). Expect 140 Apex students and, below, at least 2 in every branch x year cell.
-- ---------------------------------------------------------------------------------------------------------------------
SELECT COUNT(*) AS apex_students FROM users WHERE role = 'user' AND college_id = (SELECT id FROM colleges WHERE short_code = 'APEX');
SELECT department, branch_code, SUM(graduation_year = 2029) AS year2, SUM(graduation_year = 2028) AS year3, SUM(graduation_year = 2027) AS year4, COUNT(*) AS total
FROM users WHERE role = 'user' AND college_id = (SELECT id FROM colleges WHERE short_code = 'APEX') AND branch_code IS NOT NULL GROUP BY department, branch_code ORDER BY department, branch_code;
SELECT email, graduation_year, first_login_at, vault_ai_unlocked_at FROM users WHERE email = 'alex.chen@student.apex.edu';
